import {ChartCard} from '@github-ui/chart-card'
import {isFeatureEnabled} from '@github-ui/feature-flags'
import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {useNavigate, useParams} from '@github-ui/react-router'
import {useIsStafftools} from '@github-ui/repos-rules/use-is-stafftools'
import {useCallback, useMemo} from 'react'
import {useTimeSpan, InsightsTimeSpanMap} from '../contexts/TimeSpanContext'
import type {
  dashboardRoute,
  orgDashboardRoute,
  stafftoolsDashboardRoute,
  stafftoolsOrgDashboardRoute,
} from '../routes/dashboard-route'

type DashboardRouteConfig =
  | typeof dashboardRoute
  | typeof orgDashboardRoute
  | typeof stafftoolsDashboardRoute
  | typeof stafftoolsOrgDashboardRoute

const MAX_ACTORS = 10

export function BypassesByActorChart({routeConfig}: {routeConfig: DashboardRouteConfig}) {
  const {
    data: {sourceType, bypassesByActor, filter},
  } = useRouteQuery(routeConfig, 'mainQuery')

  const useCreatedFilter = isFeatureEnabled('rules_insights_filter_bar_created')
  const navigate = useNavigate()
  const {owner, repo, org, organizationId} = useParams<{
    owner: string
    repo: string
    org: string
    organizationId: string
  }>()
  const isStafftools = useIsStafftools()
  const {timeSpan} = useTimeSpan()

  const topActors = useMemo(() => {
    return [...bypassesByActor].sort((a, b) => b.count - a.count).slice(0, MAX_ACTORS)
  }, [bypassesByActor])

  const categories = useMemo(() => topActors.map(entry => entry.actor), [topActors])
  const data = useMemo(() => topActors.map(entry => entry.count), [topActors])

  const orgIdentifier = org ?? organizationId
  const insightsBasePath =
    sourceType === 'repository' && owner && repo
      ? isStafftools
        ? `/stafftools/repositories/${owner}/${repo}/repository_rules/insights`
        : `/${owner}/${repo}/settings/rules/insights`
      : orgIdentifier
        ? isStafftools
          ? `/stafftools/users/${orgIdentifier}/organization_rules/insights`
          : `/organizations/${orgIdentifier}/settings/rules/insights`
        : undefined

  const handlePointClick = useCallback(
    function (event: Highcharts.PointClickEventObject) {
      if (!insightsBasePath) return
      const actor = String(event.point.category)
      const timePeriod = InsightsTimeSpanMap[timeSpan] ?? 'week'
      const params = new URLSearchParams({
        actor,
        rule_status: 'bypass',
      })
      if (useCreatedFilter && filter.created) {
        params.set('created', filter.created)
      } else {
        params.set('time_period', timePeriod)
      }
      if (filter.evaluateStatus) params.set('evaluate_status', filter.evaluateStatus)
      if (filter.branch && filter.branch !== 'all') params.set('ref', filter.branch)
      if (filter.ruleset) params.set('ruleset', filter.ruleset.name)
      navigate(`${insightsBasePath}?${params.toString()}`)
    },
    [filter, insightsBasePath, navigate, timeSpan, useCreatedFilter],
  )

  return (
    <ChartCard size="medium">
      <ChartCard.Title as="h2">Bypasses by actor</ChartCard.Title>
      <ChartCard.Description>Members who have bypassed the most</ChartCard.Description>
      <ChartCard.ColumnChart
        series={[
          {
            name: 'Bypasses',
            data,
            colorByPoint: false,
          },
        ]}
        options={{
          xAxis: {
            title: 'Actor',
            categories,
          },
          yAxis: {
            title: 'Number of bypasses',
          },
        }}
        overrideOptionsNotRecommended={
          insightsBasePath
            ? {
                plotOptions: {
                  column: {
                    cursor: 'pointer',
                    point: {
                      events: {
                        click: handlePointClick,
                      },
                    },
                  },
                },
              }
            : undefined
        }
      />
    </ChartCard>
  )
}
